SELECT id, plan, effective_from, tier_limits, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE effective_from < '2024-04-17'
